import{_ as e,c as a,o as r,ag as i}from"./chunks/framework.DJBJE7_Z.js";const h=JSON.parse('{"title":"核心概念","description":"","frontmatter":{},"headers":[],"relativePath":"overview/concepts.md","filePath":"overview/concepts.md"}'),n={name:"overview/concepts.md"};function c(t,o,l,d,p,s){return r(),a("div",null,o[0]||(o[0]=[i('<h1 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h1><p>ScribbleForge 的设计围绕着一些核心概念，理解它们有助于您更高效地使用 SDK。</p><h2 id="room-协作的中心" tabindex="-1">Room：协作的中心 <a class="header-anchor" href="#room-协作的中心" aria-label="Permalink to &quot;Room：协作的中心&quot;">​</a></h2><p><code>Room</code> 是所有协作活动的起点和中心枢纽。您可以将其想象成一个虚拟会议室。</p><ul><li><strong>唯一入口</strong>：任何协作会话都必须从加入一个 <code>Room</code> 开始。</li><li><strong>状态同步</strong>：<code>Room</code> 负责同步房间内所有参与者的状态，确保数据一致性。</li><li><strong>模块管理</strong>：<code>Room</code> 内部管理着如 <code>ApplicationManager</code>、<code>UserManager</code> 等核心模块的生命周期。</li></ul><h2 id="application-功能的载体" tabindex="-1">Application：功能的载体 <a class="header-anchor" href="#application-功能的载体" aria-label="Permalink to &quot;Application：功能的载体&quot;">​</a></h2><p>在 ScribbleForge 中，所有具体的功能都是通过 <code>Application</code> (应用) 来实现的。每个 <code>Application</code> 都是一个独立的、可交互的功能单元。</p><ul><li><strong>功能模块化</strong>：白板 (<code>Whiteboard</code>)、幻灯片 (<code>Slide</code>)、音视频播放器 (<code>MediaPlayer</code>) 等都是具体的 <code>Application</code> 实现。</li><li><strong>生命周期管理</strong>：<code>Application</code> 的创建、销毁由 <code>ApplicationManager</code> 统一管理。</li><li><strong>可扩展性</strong>：您可以创建自己的 <code>Application</code> 来实现自定义功能。</li></ul><h2 id="applicationmanager-应用的总管" tabindex="-1">ApplicationManager：应用的总管 <a class="header-anchor" href="#applicationmanager-应用的总管" aria-label="Permalink to &quot;ApplicationManager：应用的总管&quot;">​</a></h2><p><code>ApplicationManager</code> 负责管理房间内所有 <code>Application</code> 的生命周期。</p><ul><li><strong>启动与终止</strong>：通过 <code>launchApp</code> 和 <code>terminalApp</code> 方法来控制应用的启动和关闭。</li><li><strong>应用注册</strong>：通过 <code>registerAppFactory</code> 可以注册自定义的应用类型。</li></ul><h2 id="windowmanager-多窗口布局" tabindex="-1">WindowManager：多窗口布局 <a class="header-anchor" href="#windowmanager-多窗口布局" aria-label="Permalink to &quot;WindowManager：多窗口布局&quot;">​</a></h2><p><code>WindowManager</code> 是一个可选但功能强大的模块，它允许您在同一个视图内容纳和管理多个 <code>Application</code> 窗口。</p><ul><li><strong>窗口化</strong>：所有通过 <code>WindowManager</code> 启动的应用都会被包裹在一个可拖动、可缩放的窗口中。</li><li><strong>层级管理</strong>：自动处理窗口之间的层叠关系和焦点切换。</li><li><strong>统一画布</strong>：为多应用协同提供了一个统一的交互空间。</li></ul><h2 id="usermanager-用户管理" tabindex="-1">UserManager：用户管理 <a class="header-anchor" href="#usermanager-用户管理" aria-label="Permalink to &quot;UserManager：用户管理&quot;">​</a></h2><p><code>UserManager</code> 负责处理房间内与用户相关的所有逻辑。</p><ul><li><strong>用户列表</strong>：维护当前房间内的在线用户列表。</li><li><strong>状态通知</strong>：通过 <code>UserListener</code> 分发用户加入、离开等事件。</li></ul><h2 id="数据流与同步" tabindex="-1">数据流与同步 <a class="header-anchor" href="#数据流与同步" aria-label="Permalink to &quot;数据流与同步&quot;">​</a></h2><p>ScribbleForge 底层使用 CRDTs (无冲突复制数据类型) 来保证多端数据的一致性。所有用户的操作都会被转换成数据变更，并通过 <code>Room</code> 内置的同步机制分发给所有参与者，从而确保每个人的视图都是同步的。</p>',19)]))}const m=e(n,[["render",c]]);export{h as __pageData,m as default};
